message.content:
{
  "hypotheses": [
    {
      "team": "home",
      "reasons": [
        {
          "text": "홈에서 4경기 무승이 이어지며 반등 압박이 커져 초반부터 전방 압박과 슈팅 수를 끌어올린다.",
          "var_ids": ["IR12-home"]
        },
        {
          "text": "최근 5경기 흐름이 칠레와 크게 다르지 않아 홈 이점과 홈 관중 변수만으로도 승부를 가져갈 여지가 있다.",
          "var_ids": ["S01-home"]
        }
      ],
      "breaks": [
        {
          "text": "중원 자원 Gilberto Mora가 결장해 전개와 창의성이 떨어지고 공격 전환이 느려진다.",
          "var_ids": ["R1"]
        },
        {
          "text": "8일 안에 이번이 3번째 경기라 체력 부하가 누적돼 후반에 라인이 내려앉는다.",
          "var_ids": ["IR11-home"]
        },
        {
          "text": "맞대결 10경기에서 평균 3.0골이 나온 열린 흐름으로 경기가 치고받는 양상이 되면 홈 이점이 희석된다.",
          "var_ids": ["S02"]
        }
      ]
    },
    {
      "team": "away",
      "reasons": [
        {
          "text": "멕시코가 8일 안에 3번째 경기를 치르는 일정 과부하 상태라 체력에서 앞서 후반 주도권을 잡는다.",
          "var_ids": ["IR11-home"]
        },
        {
          "text": "멕시코의 중원 핵심 결장으로 칠레가 중앙 숫자 우위를 점해 볼 점유와 전진 패스를 확보한다.",
          "var_ids": ["R1"]
        },
        {
          "text": "맞대결 10경기에서 승부가 자주 갈리고 평균 3.0골이 나온 열린 흐름이라 칠레의 전방 자원이 살아난다.",
          "var_ids": ["S02"]
        }
      ],
      "breaks": [
        {
          "text": "칠레도 최근 5경기에서 1승 4패로 흐름이 좋지 않아 주도권을 오래 유지하지 못한다.",
          "var_ids": ["S01-away"]
        },
        {
          "text": "멕시코가 홈에서 무승 4경기의 반등 압박을 걸어오면 칠레가 초반에 밀려 수비적으로 내려선다.",
          "var_ids": ["IR12-home"]
        },
        {
          "text": "최근 득점 흐름이 기준치 대비 낮아 결정력이 따라주지 않으면 점유해도 득점 없이 끝난다.",
          "var_ids": ["S01-away"]
        }
      ]
    }
  ],
  "scenarios": [
    {
      "id": "s1",
      "outcomes": [[3, 2], [2, 2]],
      "driver_vars": ["S02", "S01-home", "S01-away"],
      "mechanism": "맞대결 평균 3.0골의 열린 흐름과 양 팀 모두 낮은 최근 득점 보정치가 겹쳐, 수비 라인이 서로 벌어진 채 전환 공격이 반복된다. 양 팀이 번갈아 득점하며 골 수가 크게 늘어난다."
    },
    {
      "id": "s2",
      "outcomes": [[1, 3], [2, 3]],
      "driver_vars": ["IR11-home", "R1", "S01-away"],
      "mechanism": "멕시코는 8일 안에 3번째 경기로 체력이 떨어지고 중원 핵심 결장으로 전개가 단순해진다. 칠레가 중앙에서 볼을 오래 잡고 측면 전개로 밀어붙이되, 열린 맞대결 흐름 탓에 실점도 함께 내준다."
    },
    {
      "id": "s3",
      "outcomes": [[1, 0], [2, 1]],
      "driver_vars": ["IR12-home", "S01-home"],
      "mechanism": "홈팀의 4경기 무승이 반등 압박으로 바뀌어 초반부터 압박 강도를 높이고, 원정팀의 낮은 최근 득점 흐름이 이를 버티지 못한다. 한 골 차로 홈팀이 앞서며 경기가 잠긴다."
    },
    {
      "id": "s4",
      "outcomes": [[2, 1], [1, 1]],
      "driver_vars": ["IR12-home", "S01-away"],
      "mechanism": "무승 4경기의 홈팀과 1승 4패의 원정팀이 각각 자기 흐름을 되돌리려는 경기로, 양 팀 모두 실점 뒤 반응이 빨라진다. 접전에서 한 골씩 주고받거나 홈팀이 한 골 차로 뒤집는다."
    },
    {
      "id": "s5",
      "outcomes": [[0, 1], [0, 2]],
      "driver_vars": ["IR11-home", "R1", "S01-away"],
      "mechanism": "일정 과부하와 중원 결장으로 홈팀의 공격 전개가 막히고, 원정팀이 중앙 숫자 우위로 템포를 늦춘다. 골이 적게 나는 가운데 원정팀이 한두 번의 전환으로 앞선다."
    },
    {
      "id": "s6",
      "outcomes": [[2, 2], [1, 2]],
      "driver_vars": ["S02", "R1"],
      "mechanism": "중원 핵심 결장으로 홈팀의 수비 앞 공간이 열리고, 맞대결에서 반복된 다득점 흐름이 그 공간을 공격수들로 채운다. 양 팀이 득점을 주고받되 원정팀이 마지막 한 골을 더 얹는다."
    }
  ]
}
